package main

import (
    "bytes"
    "fmt"
    "mime/multipart"
    "net/http"
    "io/ioutil"
)

func main() {

	url := "https://{baseUrl}/email/1/templates"
	method := "POST"

	// Create a buffer and a multipart writer
	var requestBody bytes.Buffer
	writer := multipart.NewWriter(&requestBody)

	// Add fields to the multipart form-data
	writer.WriteField("name", "Welcome email")
	writer.WriteField("from", "Infobip <noreply@example.com>")
	writer.WriteField("replyTo", "support@example.com")
	writer.WriteField("subject", "Welcome to Infobip")
	writer.WriteField("preheader", "Welcome to Infobip")
	writer.WriteField("html", "<html><head></head><body><h2>Welcome to Infobip</h2></body></html>")
	writer.WriteField("landingPage", "1_2345")

	// Add attachments as a JSON string
	attachmentsJson := `[{"contentType":"application/pdf","fileName":"attachment.pdf","data":"{base64encoded_data}"}]`
	writer.WriteField("attachments", attachmentsJson)

	// Close the writer to finish constructing the body
	writer.Close()

	// Create the request
	req, err := http.NewRequest(method, url, &requestBody)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Set necessary headers
	req.Header.Set("Authorization", "{authorization}")
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Content-Type", writer.FormDataContentType())

	// Send the request
	client := &http.Client{}
	res, err := client.Do(req)
	if err != nil {
		fmt.Println(err)
		return
	}
	defer res.Body.Close()

	// Read and output the response
	body, err := ioutil.ReadAll(res.Body)
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println(string(body))
}

