    method: 'POST',
    hostname: '{baseUrl}',
    path: '/email/1/templates',
    headers: {
        'Authorization': '{authorization}',
        'Accept': 'application/json',
        ...form.getHeaders()  // This automatically includes 'Content-Type' and boundary
